# BabyEng TTS 推理服务（PRD 9.4：首选 Piper ONNX）
# 模型文件挂载到 /models/piper/，缺失时返回 503 由后端降级为「发音暂时不可用」（4.1.3）
# 依赖：pip install piper-tts fastapi uvicorn

import io
import os
import wave
from pathlib import Path

from fastapi import FastAPI, HTTPException, Query
from fastapi.responses import Response

app = FastAPI(title="BabyEng TTS", version="0.4.0")

MODEL_DIR = Path(os.environ.get("MODEL_DIR", "/models/piper"))
DEFAULT_VOICE = os.environ.get("PIPER_VOICE", "en_US-mike-medium")
ALLOWED_VOICES = {
    "en_US-mike-medium",
    "en_US-amy-medium",
    "en_US-ryan-medium",
    "en_US-kristin-medium",
    "en_US-hfc_female-medium",
    "en_US-hfc_male-medium",
}

# 音色缓存：voice -> PiperVoice 实例
_voices = {}
_ready = False


def _load_voice(voice: str):
    """加载指定音色；成功返回实例，失败返回 None"""
    if voice not in ALLOWED_VOICES:
        return None
    try:
        from piper import PiperVoice
    except ImportError:
        return None
    model_path = MODEL_DIR / f"{voice}.onnx"
    config_path = MODEL_DIR / f"{voice}.onnx.json"
    if not (model_path.exists() and config_path.exists()):
        return None
    try:
        return PiperVoice.load(str(model_path), str(config_path))
    except Exception as e:  # noqa: BLE001
        print(f"[tts] load {voice} failed: {e}")
        return None


def _any_model_available() -> bool:
    if not MODEL_DIR.exists():
        return False
    if not DEFAULT_VOICE:
        return False
    return (MODEL_DIR / f"{DEFAULT_VOICE}.onnx").exists()


_default_voice = _load_voice(DEFAULT_VOICE)
if _default_voice is not None:
    _voices[DEFAULT_VOICE] = _default_voice
_ready = _default_voice is not None


@app.get("/healthz")
def healthz():
    return {"ok": True}


@app.get("/readyz")
def readyz():
    return {"ok": _ready, "voice": DEFAULT_VOICE}


@app.get("/synthesize")
def synthesize(
    text: str = Query(...),
    voice: str = Query(DEFAULT_VOICE),
    length_scale: float = Query(0.8, ge=0.5, le=1.5),
):
    """合成文本 → 16k 单声道 wav。模型缺失 → 503（后端降级提示）"""
    if not _ready:
        raise HTTPException(status_code=503, detail="tts model not ready")

    if voice not in _voices:
        v = _load_voice(voice)
        if v is None:
            raise HTTPException(status_code=503, detail=f"voice {voice} not available")
        _voices[voice] = v
    v = _voices[voice]

    wav_bytes = io.BytesIO()
    try:
        from piper.config import SynthesisConfig

        with wave.open(wav_bytes, "wb") as f:
            v.synthesize_wav(
                text,
                f,
                syn_config=SynthesisConfig(length_scale=length_scale),
            )
    except Exception as e:  # noqa: BLE001
        raise HTTPException(status_code=500, detail=f"synthesize error: {e}")
    return Response(
        content=wav_bytes.getvalue(),
        media_type="audio/wav",
        headers={"Cache-Control": "no-cache"},
    )


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("PORT", "8101")))
---COMPOSE---
# BabyEng Docker Compose 编排（PRD 9.9）
# 服务：web(nginx+前端) / backend(Rust) / tts(Piper) / asr(sherpa-onnx) / llm(可选, profile: full)
# 用法：
#   MVP（无 LLM）：        docker compose --profile mvp up -d --build
#   Full（含本地 LLM）：   docker compose --profile full up -d --build
# 模型文件放 models volume（tts/piper/en_US-mike-medium.onnx 等），见 deploy/README.md

name: babyeng

services:
  web:
    build:
      context: ..
      dockerfile: deploy/Dockerfile.web
    ports:
      - "${WEB_BIND_ADDR:-127.0.0.1}:${WEB_PORT:-80}:80"
    depends_on:
      backend:
        condition: service_started
    restart: unless-stopped

  backend:
    build:
      context: ..
      dockerfile: deploy/Dockerfile.backend
    environment:
      BIND_ADDR: "0.0.0.0:8080"
      DATABASE_URL: "sqlite:///data/babyeng.db"
      SEED_DIR: "/app/data/seed"
      AUDIO_DIR: "/data/audio"
      STATIC_DIR: "/app/static"
      TTS_URL: "http://tts:8101"
      ASR_URL: "http://asr:8102"
      LLM_URL: "http://llm:8103"
      SVC_TIMEOUT_SECS: "15"
      AUTH_FILE: "/app/auth.json"
    volumes:
      - data:/data
      - audio:/data/audio
      - "${AUTH_FILE:-./auth.json}:/app/auth.json:ro"
    depends_on:
      tts:
        condition: service_healthy
      asr:
        condition: service_healthy
    restart: unless-stopped
    healthcheck:
      test: ["CMD", "wget", "-qO-", "http://127.0.0.1:8080/api/healthz"]
      interval: 10s
      timeout: 3s
      retries: 5

  tts:
    build:
      context: ../services/tts
    environment:
      MODEL_DIR: "/models/piper"
      PIPER_VOICE: "en_US-mike-medium"
      PORT: "8101"
    volumes:
      - models:/models
    restart: unless-stopped
    healthcheck:
      test: ["CMD", "python", "-c", "import urllib.request;urllib.request.urlopen('http://127.0.0.1:8101/readyz')"]
      interval: 15s
      timeout: 5s
      retries: 10
      start_period: 20s

  asr:
    build:
      context: ../services/asr
    environment:
      MODEL_DIR: "/models/asr"
      PORT: "8102"
    volumes:
      - models:/models
    restart: unless-stopped
    healthcheck:
      test: ["CMD", "python", "-c", "import urllib.request;urllib.request.urlopen('http://127.0.0.1:8102/readyz')"]
      interval: 15s
      timeout: 5s
      retries: 10
      start_period: 20s

  llm:
    profiles: ["full"]
    build:
      context: ../services/llm
    environment:
      OPENAI_BASE_URL: "${LLM_BASE_URL:-http://host.docker.internal:11434/v1}"
      OPENAI_API_KEY: "${LLM_API_KEY:-}"
      LLM_MODEL: "${LLM_MODEL:-qwen2.5:7b-instruct}"
      PORT: "8103"
    extra_hosts:
      - "host.docker.internal:host-gateway"
    restart: unless-stopped
    healthcheck:
      test: ["CMD", "python", "-c", "import urllib.request;urllib.request.urlopen('http://127.0.0.1:8103/readyz')"]
      interval: 30s
      timeout: 5s
      retries: 10

volumes:
  models:     # 模型文件（tts/piper、asr/... 首次需手动放入）
  audio:      # 录音与合成音频
  data:       # sqlite 文件
