/// 二选一确认（PRD 4.1：你是说 A 还是 B？）
#[derive(Deserialize)]
struct ConfirmBody {
    target_type: String,
    target_id: String,
    child_id: Option<String>,
}

async fn ask_confirm(
    State(state): State<SharedState>,
    Extension(user): Extension<AuthUser>,
    Json(body): Json<ConfirmBody>,
) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    if let Some(id) = body.child_id.as_deref() {
        auth::require_child(pool, &user, id).await?;
    }
    let result = match body.target_type.as_str() {
        "word" => {
            let w = store::get_word(pool, &body.target_id).await?;
            let Some(w) = w else {
                return Err(AppError::NotFound("词条不存在".into()));
            };
            AskResult {
                target_type: "word".into(),
                target_id: w.id.clone(),
                zh: w.zh,
                en: w.en,
                phonetic: w.phonetic,
                phonetic_source: Some(w.phonetic_source),
                category: Some(w.category),
                scene: None,
                example_en: w.example_en,
                example_zh: w.example_zh,
                example_context: None,
                mother_tip: w.mother_tip,
                image_emoji: Some(w.image_emoji),
                match_level: "L2-confirm".into(),
                tts_available: false,
                tts_url: None,
            }
        }
        "sentence" => {
            let s = store::get_sentence(pool, &body.target_id).await?;
            let Some(s) = s else {
                return Err(AppError::NotFound("句子不存在".into()));
            };
            AskResult {
                target_type: "sentence".into(),
                target_id: s.id.clone(),
                zh: s.zh,
                en: s.en,
                phonetic: s.phonetic,
                phonetic_source: Some(s.phonetic_source),
                category: None,
                scene: Some(s.scene),
                example_en: None,
                example_zh: None,
                example_context: s.example_context,
                mother_tip: None,
                image_emoji: None,
                match_level: "L2-confirm".into(),
                tts_available: false,
                tts_url: None,
            }
        }
        _ => return Err(AppError::BadRequest("target_type 非法".into())),
    };

    // 计一次 ask
    if let Some(cid) = &body.child_id {
        crate::logic::record_learning(
            pool,
            cid,
            &result.target_type,
            &result.target_id,
            "ask",
            None,
            None,
        )
        .await?;
    }

    Ok(Json(json!({ "ok": true, "result": result })))
}

/// 匹配管线主流程（L0 → L1 → L2 → 兜底）
async fn run_pipeline(
    state: &SharedState,
    raw: &str,
    asr_confidence: Option<f64>,
    family_id: Option<&str>,
    child_id: Option<&str>,
) -> AskResponse {
    let pool = &state.pool;
    let normalized = crate::normalize::normalize(raw);

    let matcher = state.matcher.read().await;
    let outcome = matcher.match_query(&normalized, raw);
    drop(matcher);

    let tts_ready = state.inference.ready.read().map(|r| r.tts).unwrap_or(false);

    match outcome {
        Match::Hit(target, level) => {
            let mut result = target.to_ask_result();
            result.match_level = level.to_string();
            match store::enrich_ask_result(pool, result).await {
                Ok(r) => {
                    result = r;
                    // TTS 音频 URL（发音是否可用取决于 TTS 服务）
                    result.tts_available = tts_ready;
                    if tts_ready {
                        result.tts_url = Some(format!(
                            "/api/tts/audio?text={}&voice=en_US-mike-medium&rate=0.8",
                            percent_encoding::utf8_percent_encode(
                                &result.en,
                                percent_encoding::NON_ALPHANUMERIC
                            )
                        ));
                    }
                    // 记录 ask 学习动作
                    if let Some(cid) = child_id {
                        let _ = crate::logic::record_learning(
                            pool,
                            cid,
                            &result.target_type,
                            &result.target_id,
                            "ask",
                            None,
                            None,
                        )
                        .await;
                    }
                    AskResponse {
                        status: if tts_ready { "hit" } else { "tts_only_down" }.into(),
                        result: Some(result),
                        candidates: vec![],
                        recognized_text: Some(raw.to_string()),
                        normalized_text: Some(normalized.clone()),
                        unmatched_id: None,
                        message: None,
                    }
                }
                Err(_) => AskResponse {
                    status: "nomatch".into(),
                    result: None,
                    candidates: vec![],
                    recognized_text: Some(raw.to_string()),
                    normalized_text: Some(normalized),
                    unmatched_id: None,
                    message: Some("内部错误，请重试".into()),
                },
            }
        }
        Match::Ambiguous(cands) => {
            let mut candidates = Vec::new();
            for c in cands {
                let mut r = c.to_ask_result();
                r.match_level = "L2-ambiguous".into();
                if let Ok(enriched) = store::enrich_ask_result(pool, r).await {
                    let mut enriched = enriched;
                    enriched.tts_available = tts_ready;
                    candidates.push(enriched);
                }
            }
            AskResponse {
                status: "ambiguous".into(),
                result: None,
                candidates,
                recognized_text: Some(raw.to_string()),
                normalized_text: Some(normalized),
                unmatched_id: None,
                message: Some("你是说哪一个？".into()),
            }
        }
        Match::Miss => {
            // 彻底未命中：相近词推荐 + 文字输入 + 静默写入未命中表（8.8）
            let fam_id = family_id.unwrap_or_default().to_string();

            let unmatched_id = if fam_id.is_empty() {
                None
            } else {
                logic_unmatched::upsert_unmatched(pool, &fam_id, raw, &normalized, asr_confidence)
                    .await
                    .ok()
            };

//! 健康检查与就绪探针（PRD 9.10：/healthz、/readyz 供容器编排探活）

use axum::extract::State;
use axum::routing::get;
use axum::{Json, Router};
use serde_json::json;

use crate::state::SharedState;

pub fn router() -> Router<SharedState> {
    Router::new()
        .route("/api/healthz", get(healthz))
        .route("/api/readyz", get(readyz))
}

async fn healthz() -> Json<serde_json::Value> {
    Json(json!({ "ok": true, "service": "babyeng-backend", "version": "0.4.0" }))
}

async fn readyz(State(state): State<SharedState>) -> Json<serde_json::Value> {
    // 推理服务就绪状态（PRD 5.4「正在启动」提示条依据）
    let ready = {
        let r = state.inference.ready.read().unwrap();
        (r.tts, r.asr, r.llm)
    };
    Json(json!({
        "ok": true,
        "services": {
            "tts": ready.0,
            "asr": ready.1,
            "llm": ready.2,
        }
    }))
}
//! BabyEng 业务后端入口（PRD 9.1 / 9.3）
//! Rust(axum) + SQLite(sqlx) + 推理服务分离（HTTP 调用 TTS/ASR/LLM）

#![allow(clippy::uninlined_format_args)]

mod config;
mod auth;
mod db;
mod error;
mod inference;
mod logic;
mod matcher;
mod models;
mod normalize;
mod routes;
mod state;
mod store;

use std::time::Duration;

use axum::Router;
use tower_http::trace::TraceLayer;
use tracing::info;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info,sqlx=warn".into()),
        )
        .init();

    let cfg = config::Config::from_env();
    let state = match state::AppState::new(cfg.clone()).await {
        Ok(s) => s,
        Err(e) => {
            tracing::error!("启动失败: {}", e);
            std::process::exit(1);
        }
    };

    // 后台任务：定期刷新推理服务就绪状态（PRD 5.4「正在启动」提示条依据）
    {
        let state = state.clone();
        tokio::spawn(async move {
            let mut tick = tokio::time::interval(Duration::from_secs(10));
            loop {
                tick.tick().await;
                state.inference.refresh_ready();
            }
        });
    }

    // api_router 内部已 with_state，返回 Router<()>；
    // 静态资源用 fallback_service（axum 0.8 根路径嵌套改为 fallback），
    // 未命中静态文件时回退 index.html（SPA 路由，PWA 可直接刷新子路径）。
    // 注意：ServeDir 的 not_found_service 会强制 404 状态码，SPA 回退须用 .fallback()
    let index_file = format!("{}/index.html", cfg.static_dir);
    let fallback = tower_http::services::ServeDir::new(&cfg.static_dir)
        .fallback(tower_http::services::ServeFile::new(&index_file));
    let app = Router::new()
        .merge(routes::api_router(state.clone()))
        .layer(TraceLayer::new_for_http())
        .fallback_service(fallback);

    let addr = &cfg.bind_addr;
    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .unwrap_or_else(|e| {
            tracing::error!("监听 {} 失败: {}", addr, e);
            std::process::exit(1);
        });
    info!("BabyEng backend listening on http://{}", addr);
    info!("static dir: {}", cfg.static_dir);
    axum::serve(listener, app).await.unwrap();
}
